//! Raw EndpointSecurity bindings, transcribed from the macOS SDK headers
//! (`ESTypes.h`, `ESMessageCore.h`, `ESMessage.h`, `ESClient.h`).
//!
//! Names are the C names on purpose: this file is meant to be read beside the
//! header, and `anchors_test.zig` looks types and enumerators up by those names
//! to compare every size, offset and value against what Apple's clang computes
//! (`layout_anchors.zig`, generated by `tools/gen_layout_anchors.py`).
//!
//! Conventions:
//!   * `_Nonnull T *` → `*T`; `_Nullable T *` → `?*T`; arrays of tokens → `?[*]T`.
//!   * Anonymous C unions/structs become named fields (`v` for the versioned
//!     tail union, `fields` for the struct inside it); the anchor test resolves
//!     C's promoted member names through those.
//!   * Fields marked "message version >= N" in the header are only meaningful
//!     when `es_message_t.version >= N`; see `versioned.zig` for the table and
//!     the gated accessors in `message.zig` / `event.zig`.
//!   * Functions introduced after macOS 10.15 are weak imports (`?*const fn`)
//!     so a binary can load on an older macOS and check for null at runtime.
//!
//! `es_handler_block_t` is an Objective-C block; build one with
//! `darwin_kit.block` (see `client.zig`). A plain function pointer is not a
//! block and must never be passed to `es_new_client`.

const std = @import("std");
const darwin = @import("darwin_kit");
pub const enums = @import("enums.zig");

