/// Length-prefixed binary blob.
pub const es_token_t = extern struct {
    size: usize,
    data: ?[*]const u8,

    pub fn slice(self: es_token_t) []const u8 {
        return if (self.data) |d| d[0..self.size] else "";
    }
};

/// Length-prefixed string; `length` is what strlen() would return and the
/// bytes are usually followed by a NUL, but only `length` bytes are guaranteed.
pub const es_string_token_t = extern struct {
    length: usize,
    data: ?[*]const u8,

    pub fn slice(self: es_string_token_t) []const u8 {
        return if (self.data) |d| d[0..self.length] else "";
    }
};

pub const es_muted_path_t = extern struct {
    type: es_mute_path_type_t,
    event_count: usize,
    events: ?[*]const es_event_type_t,
    path: es_string_token_t,

    pub fn eventSlice(self: es_muted_path_t) []const es_event_type_t {
        return if (self.events) |e| e[0..self.event_count] else &.{};
    }
};

pub const es_muted_paths_t = extern struct {
