// ─────────────────────── system types ES embeds ───────────────────────

pub const audit_token_t = darwin.AuditToken;
pub const uuid_t = [16]u8;
pub const pid_t = std.c.pid_t;
pub const uid_t = std.c.uid_t;
pub const gid_t = std.c.gid_t;
pub const mode_t = u16;
pub const dev_t = i32;
pub const cpu_type_t = i32;
pub const cpu_subtype_t = i32;
pub const user_addr_t = u64;
pub const user_size_t = u64;
pub const timespec = std.c.timespec;
pub const timeval = std.c.timeval;
pub const struct_stat = std.c.Stat;

/// `acl_t` from <sys/acl.h>: pointer to an opaque `struct _acl`. ES documents
/// that the ACLs it delivers are not compatible with the `acl_*` functions.
pub const acl_t = ?*opaque {};

/// <sys/attr.h>
pub const struct_attrlist = extern struct {
    bitmapcount: u16,
    reserved: u16,
    commonattr: u32,
    volattr: u32,
    dirattr: u32,
    fileattr: u32,
    forkattr: u32,
};

/// <sys/mount.h>, 64-bit inode layout (`struct statfs` with `_DARWIN_FEATURE_64_BIT_INODE`).
pub const struct_statfs = extern struct {
    f_bsize: u32,
    f_iosize: i32,
    f_blocks: u64,
    f_bfree: u64,
    f_bavail: u64,
    f_files: u64,
    f_ffree: u64,
    f_fsid: extern struct { val: [2]i32 },
    f_owner: uid_t,
    f_type: u32,
    f_flags: u32,
    f_fssubtype: u32,
    f_fstypename: [16]u8,
    f_mntonname: [1024]u8,
    f_mntfromname: [1024]u8,
    f_flags_ext: u32,
    f_reserved: [7]u32,

    pub fn mountPoint(self: *const struct_statfs) []const u8 {
        return std.mem.sliceTo(&self.f_mntonname, 0);
    }
    pub fn mountedFrom(self: *const struct_statfs) []const u8 {
        return std.mem.sliceTo(&self.f_mntfromname, 0);
    }
    pub fn fsTypeName(self: *const struct_statfs) []const u8 {
        return std.mem.sliceTo(&self.f_fstypename, 0);
    }
};

