/// One delivered event. The C struct ends with a flexible `uint64_t opaque[]`
/// that is omitted here; never copy an `es_message_t` by value, only hold
/// pointers into what ES delivered and retain/release them.
pub const es_message_t = extern struct {
    version: u32,
    time: timespec,
    mach_time: u64,
    deadline: u64,
    process: *es_process_t,
    seq_num: u64, // message version >= 2
    action_type: es_action_type_t,
    action: extern union {
        auth: es_event_id_t,
        notify: es_result_t,
    },
    event_type: es_event_type_t,
    event: es_events_t,
    thread: ?*es_thread_t, // message version >= 4
    global_seq_num: u64, // message version >= 4
};

